#!/usr/bin/env bash
# СУДИТ: hooks/authorization-lib.sh
# probe_D1245 — короткие поручения владельца признаются авторизацией. Слова — из замера по корпусу (4 ноября 2026, 414
#   расшифровок, голой репликой, на 92518e87 `auth_classify` → 1): «бери» 5, «давай» 1, «пуш» 10, «чини» 8, «ставь» 3,
#   «строй» 3, «правь» 2, «пиши» 2, «глянь» 1 и в чужой раскладке «lfkmit» («дальше») 2, «jr» («ок») 2, «lf» («да») 1.
#   Реплика короче 12 байт (6 кириллических букв: awk в macOS считает байты) судится только перечнями
#   (`hooks/authorization-lib.sh`), и без этих слов `budget-gate.sh` окликал правку по поручению (4 ноября 2026, «бери»).
# Контроли: «делай» признаётся; вопрос без маркеров и короткие реакции без «?» не признаются. Реакции «вот», «хм», «опять»
#   идут через ветку длины, а не через «?» (скептик opus по 92518e87, M4): вырожденная починка «порог 1» даёт рамку, а не 0.
# Код: 0 — все слова признаны; 1 — нет (названо); 2 — нет библиотеки, контроль не прошёл либо классификатор не смог измерить.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
[ -f "$R/hooks/authorization-lib.sh" ] && [ -f "$R/hooks/portable-lib.sh" ] || exit 2
cd "$R/hooks" || exit 2
. ./portable-lib.sh && . ./authorization-lib.sh || exit 2
auth_classify "делай" >/dev/null || { echo "рамка: «делай» не признан поручением" >&2; exit 2; }
# «эй», «ой», «иии», «ээээй» — реакции на окончание повелительного без порога длины и согласной; «nice», «ytn» («нет») —
# латиница, не продолжение: без них мутанты «снят порог» и «любая латиница — поручение» давали пробе 0 (скептик opus по
# a473b8a6, M1).
for q in "как лучше устроить дизайн?" вот хм опять эй ой иии ээээй nice ytn; do
    auth_classify "$q" >/dev/null; rc=$?
    [ "$rc" -eq 1 ] || { echo "рамка: «${q}» — код ${rc}, а не 1 (не поручение)" >&2; exit 2; }
done
miss=""
for w in бери давай пуш чини ставь строй правь пиши глянь lfkmit jr lf; do
    auth_classify "$w" >/dev/null; rc=$?
    case "$rc" in
        0) ;;
        1) miss="$miss $w" ;;
        *) echo "рамка: «${w}» — классификатор не смог измерить (код ${rc})" >&2; exit 2 ;;
    esac
done
[ -z "$miss" ] && { echo "короткие поручения признаны авторизацией"; exit 0; }
echo "не признаны поручением:$miss"
exit 1
